def get_intersection(headA, headB):
    """
    Return the node at which two linked lists intersect (same node object), or None if they don't.
    """
    if not headA or not headB:
        return None

    lenA = 0
    lenB = 0
    currA = headA
    currB = headB

    while currA:
        lenA += 1
        currA = currA.next

    while currB:
        lenB += 1
        currB = currB.next

    currA = headA
    currB = headB

    if lenA > lenB:
        for _ in range(lenA - lenB):
            currA = currA.next
    else:
        for _ in range(lenB - lenA):
            currB = currB.next


    while currA and currB:
        if currA is currB:  
            return currA
        currA = currA.next
        currB = currB.next

    return None
    pass

