def check_brackets(s):
    stack = []
    pairs = {')': '(', ']':'[', '}':'{'}

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack or stack.pop() != pairs[char]:
                return False

    return not stack

def simulate_queue(customers):
    queue = list(customers)
    result = {}
    current_time = 0

    while queue:
        name, service_time = queue.pop(0)
        current_time += service_time
        result[name] = current_time
    return result

def next_greater(nums):
    result = [-1] * len(nums)
    stack = []

    for i in range(len(nums) - 1, -1, -1):
        while stack and stack[-1] <= nums[i]:
            stack.pop()

        if stack:
            result[i] = stack[-1]

        stack.append(nums[i])
    return result

