def flood_fill(grid, row, col, new_color):
    result = [r[:] for r in grid]
    old_color = result[row][col]

    if old_color == new_color:
        return result

    stack = [(row, col)]

    while stack:
        r, c = stack.pop()
        result[r][c] = new_color

        for nr, nc in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
            if 0 <= nr < len(result) and 0 <= nc < len(result[0]):
                if result[nr][nc] == old_color:
                    stack.append((nr, nc))

    return result

def check_loan(age, income, credit_score, existing_loans):
    if age < 18:
        return "Rejected: Underage"
    elif income < 15000:
        return "Rejected: Insufficient income"
    elif credit_score < 600:
        return "Rejected: Poor credit score"
    elif existing_loans >= 3:
        return "Rejected: Too many existing loans"
    elif credit_score >= 750 and income >= 50000:
        return "Approved: Premium"
    elif credit_score >= 700:
        return "Approved: Standard"
    else:
        return "Approved: Basic"

