class TicketBooking:
    def __init__(self) -> None:
        self.__seats: dict[str, dict] = {}

    def add_seat(self, seat_id: str, price: float) -> None:
        if seat_id in self.__seats:
            raise ValueError(f"Seat '{seat_id}' already exists.")
        if price <= 0:
            raise ValueError("Price must be greater than 0.")

        self.__seats[seat_id] = {
            "status": "available",
            "holder": None,
            "price": float(price),
        }

    def book_seat(self, seat_id: str, holder_name: str) -> None:
        if seat_id not in self.__seats:
            raise ValueError(f"Seat '{seat_id}' not found.")
        if self.__seats[seat_id]["status"] == "booked":
            raise ValueError(f"Seat '{seat_id}' is already booked.")

        self.__seats[seat_id]["status"] = "booked"
        self.__seats[seat_id]["holder"] = holder_name

    def cancel_booking(self, seat_id: str) -> None:
        if seat_id not in self.__seats:
            raise ValueError(f"Seat '{seat_id}' not found.")
        if self.__seats[seat_id]["status"] == "available":
            raise ValueError(f"Seat '{seat_id}' is not currently booked.")

        self.__seats[seat_id]["status"] = "available"
        self.__seats[seat_id]["holder"] = None

    def available_seats(self) -> list[str]:
        return sorted(
            seat_id
            for seat_id, info in self.__seats.items()
            if info["status"] == "available"
        )

class BankAccount:
    def __init__(self):
        self.__balance = 0

    def deposit(self, amount):
        if (amount <= 0):
            raise ValueError("Your amount is 0 or less than 0")
        else:
            self.__balance += amount

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Amount must be greater than 0")
        elif amount > self.__balance:
            raise ValueError("Insufficient funds")
        self.__balance -= amount

    def get_balance(self):
        return self.__balance

    def transfer(self, amount, target):
        self.withdraw(amount)
        target.deposit(amount)

