def is_palindrome(s):
    """
    Recursively check if s is a palindrome (no loops or string reversal).
    """
    if len(s) <= 1:
        return True

    if s[0] != s[-1]:
        return False

    return is_palindrome(s[1:-1])

def flatten(nested):
    """
    Recursively flatten an arbitrarily nested list into a single flat list of integers.
    """
    result = []

    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)

    return result

def count_paths(rows, cols):
    """
    Recursively count the unique top-left to bottom-right paths in a rows x cols grid (right/down moves only).
    """
    if rows == 1 or cols == 1:
        return 1

    return count_paths(rows - 1, cols) + count_paths(rows, cols - 1)

def count_paths_memo(rows, cols, memo=None):
    """
    Same as count_paths, with memoization to avoid recomputation.
    """
    if memo is None:
        memo = {}

    if rows == 1 or cols == 1:
        return 1

    if (rows, cols) in memo:
        return memo[(rows, cols)]

    memo[(rows, cols)] = (
        count_paths_memo(rows - 1, cols, memo)
        + count_paths_memo(rows, cols - 1, memo)
    )

    return memo[(rows, cols)]

def count_occurrences(text, sub):
    """
    Return the number of non-overlapping, case-insensitive occurrences of sub in text.
    """
    if not sub:
        return 0
    return text.lower().count(sub.lower())

