class HospitalSystem:
    def __init__(self):
        self.doctors = {}
        self.appointments = []

    def add_doctor(self, doctor_id, name, specialty):
        if doctor_id in self.doctors:
            raise ValueError("Doctor ID already exists")

        self.doctors[doctor_id] = Doctor(doctor_id, name, specialty)

    def book_appointment(self, patient_name, doctor_id, date):
        if doctor_id not in self.doctors:
            raise ValueError("Doctor not found")

        for appointment in self.appointments:
            if (
                appointment["doctor_id"] == doctor_id
                and appointment["date"] == date
            ):
                raise ValueError("Doctor already has an appointment on this date")

        self.appointments.append({
            "patient_name": patient_name,
            "doctor_id": doctor_id,
            "date": date
        })

    def cancel_appointment(self, patient_name, doctor_id, date):
        for appointment in self.appointments:
            if (
                appointment["patient_name"] == patient_name
                and appointment["doctor_id"] == doctor_id
                and appointment["date"] == date
            ):
                self.appointments.remove(appointment)
                return

        raise ValueError("Appointment not found")

    def get_appointments(self, doctor_id):
        if doctor_id not in self.doctors:
            raise ValueError("Doctor not found")

        result = []

        for appointment in self.appointments:
            if appointment["doctor_id"] == doctor_id:
                result.append(
                    f'{appointment["date"]}: {appointment["patient_name"]}'
                )

        return sorted(result)

    def get_patient_doctors(self, patient_name):
        doctor_names = set()

        for appointment in self.appointments:
            if appointment["patient_name"] == patient_name:
                doctor = self.doctors[appointment["doctor_id"]]
                doctor_names.add(doctor.name)

        return sorted(doctor_names)

class StudentManager:
    def __init__(self):
        self.students = {}

    def enroll(self, student_name, course_name):
        if student_name not in self.students:
            self.students[student_name] = set()

        if course_name in self.students[student_name]:
            raise ValueError("Student already enrolled")

        self.students[student_name].add(course_name)

    def drop(self, student_name, course_name):
        if (
            student_name not in self.students
            or course_name not in self.students[student_name]
        ):
            raise ValueError("Student not enrolled")

        self.students[student_name].remove(course_name)

        if not self.students[student_name]:
            del self.students[student_name]

    def get_courses(self, student_name):
        if student_name not in self.students:
            return []

        return sorted(self.students[student_name])

    def get_students(self, course_name):
        result = []

        for student_name, courses in self.students.items():
            if course_name in courses:
                result.append(student_name)

        return sorted(result)

    def top_student(self):
        if not self.students:
            return None

        max_courses = max(
            len(courses) for courses in self.students.values()
        )

        top_students = [
            student_name
            for student_name, courses in self.students.items()
            if len(courses) == max_courses
        ]

        return sorted(top_students)[0]

