class Restaurant:
    def __init__(self):
        self.menu = {}
        self.orders = {}

    def add_menu_item(self, item_id, name, price, category):
        if item_id in self.menu:
            raise ValueError("Item ID already exists")

        if price <= 0:
            raise ValueError("Invalid price")

        self.menu[item_id] = MenuItem(
            item_id, name, price, category
        )

    def place_order(self, table_number, item_id, quantity=1):
        if item_id not in self.menu:
            raise ValueError("Item not found")

        if quantity <= 0:
            raise ValueError("Invalid quantity")

        if table_number not in self.orders:
            self.orders[table_number] = {}

        if item_id not in self.orders[table_number]:
            self.orders[table_number][item_id] = 0

        self.orders[table_number][item_id] += quantity

    def remove_from_order(self, table_number, item_id, quantity=1):
        if quantity <= 0:
            raise ValueError("Invalid quantity")

        if table_number not in self.orders:
            raise ValueError("Order not found")

        if item_id not in self.orders[table_number]:
            raise ValueError("Item not found in order")

        if quantity > self.orders[table_number][item_id]:
            raise ValueError("Quantity exceeds order")

        self.orders[table_number][item_id] -= quantity

        if self.orders[table_number][item_id] == 0:
            del self.orders[table_number][item_id]

    def get_bill(self, table_number):
        if table_number not in self.orders:
            return "No orders for table"

        if not self.orders[table_number]:
            return "No orders for table"

        lines = []
        total = 0

        ordered_items = []

        for item_id, quantity in self.orders[table_number].items():
            item = self.menu[item_id]
            ordered_items.append((item.name, item, quantity))

        ordered_items.sort()

        for name, item, quantity in ordered_items:
            subtotal = item.price * quantity
            total += subtotal

            lines.append(
                f"{name} x{quantity} = PHP {round(float(subtotal), 2)}"
            )

        lines.append(
            f"Total: PHP {round(float(total), 2)}"
        )

        return "\n".join(lines)

    def get_menu_by_category(self, category):
        result = []

        for item in self.menu.values():
            if item.category == category:
                result.append(item.name)

        return sorted(result)

class Product:
    def __init__(self, name, price, stock):
        self.name = name
        self.price = price
        self.stock = stock


class Store:
    def __init__(self):
        self.products = {}

    def add_product(self, name, price, stock):
        self.products[name] = Product(name, price, stock)

    def buy(self, name, quantity):
        if name not in self.products:
            raise ValueError("Product not found")

        if quantity <= 0:
            raise ValueError("Invalid quantity")

        product = self.products[name]

        if product.stock < quantity:
            raise ValueError("Insufficient stock")

        product.stock -= quantity

    def restock(self, name, quantity):
        if name not in self.products:
            raise ValueError("Product not found")

        if quantity <= 0:
            raise ValueError("Invalid quantity")

        self.products[name].stock += quantity

    def total_value(self):
        return round(
            sum(
                product.price * product.stock
                for product in self.products.values()
            ),
            2
        )

    def available_products(self):
        return sorted(
            product.name
            for product in self.products.values()
            if product.stock > 0
        )

