class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def find_middle(head):

    if head is None:
        return None

    slow = head
    fast = head

    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next

    return slow.val

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def delete_node(head, val):

    if head is None:
        return None

    if head.val == val:
        return head.next

    current = head
    while current.next is not None:
        if current.next.val == val:
            current.next = current.next.next
            break
        current = current.next

    return head

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def merge_sorted(l1, l2):

    dummy = ListNode(0)
    current = dummy

    while l1 is not None and l2 is not None:
        if l1.val <= l2.val:
            current.next = l1  
            l1 = l1.next       
        else:
            current.next = l2  
            l2 = l2.next       

        current = current.next 

    if l1 is not None:
        current.next = l1
    elif l2 is not None:
        current.next = l2

    return dummy.next

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def max_depth(root):
    """
    Return the maximum depth of the binary tree (0 for an empty tree).
    """
    if root is None:
        return 0

    return 1 + max(max_depth(root.left), max_depth(root.right))

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def lca(root, p, q):
    """
    Return the value of the lowest common ancestor of the nodes with values p and q.
    """
    if root is None:
        return None

    if root.val == p or root.val == q:
        return root.val

    left = lca(root.left, p, q)
    right = lca(root.right, p, q)

    if left is not None and right is not None:
        return root.val

    return left if left is not None else right

