class HospitalSystem:
    def __init__(self):
        self.doctors = {}
        self.appointments = []

    def add_doctor(self, doctor_id, name, specialty):
        if doctor_id in self.doctors:
            raise ValueError("Doctor ID already exists")

        self.doctors[doctor_id] = Doctor(doctor_id, name, specialty)

    def book_appointment(self, patient_name, doctor_id, date):
        if doctor_id not in self.doctors:
            raise ValueError("Doctor not found")

        for appointment in self.appointments:
            if appointment[1] == doctor_id and appointment[2] == date:
                raise ValueError("Doctor already has an appointment")

        self.appointments.append((patient_name, doctor_id, date))

    def cancel_appointment(self, patient_name, doctor_id, date):
        for appointment in self.appointments:
            if appointment == (patient_name, doctor_id, date):
                self.appointments.remove(appointment)
                return

        raise ValueError("Appointment not found")

    def get_appointments(self, doctor_id):
        if doctor_id not in self.doctors:
            raise ValueError("Doctor not found")

        result = []

        for patient_name, doc_id, date in self.appointments:
            if doc_id == doctor_id:
                result.append(f"{date}: {patient_name}")

        return sorted(result)

    def get_patient_doctors(self, patient_name):
        doctors = []

        for patient, doctor_id, date in self.appointments:
            if patient == patient_name:
                doctors.append(self.doctors[doctor_id].name)

        return sorted(set(doctors))

def is_palindrome(s):
    if len(s) <= 1:
        return True

    if s[0] != s[-1]:
        return False

    return is_palindrome(s[1:-1])

def flatten(nested):
    result = []

    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)

    return result

