def spiral_order(matrix):
    """
    Return all elements of matrix in clockwise spiral order starting top-left.
    """
    if not matrix or not matrix[0]:
        return []

    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # 1. Traverse right across top boundary
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # 2. Traverse down along right boundary
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        # 3. Traverse left across bottom boundary
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        # 4. Traverse up along left boundary
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result

class Expression:
    def evaluate(self):
        return 0

    def __str__(self):
        return "0"


class Number(Expression):
    def __init__(self, value):
        self.value = value

    def evaluate(self):
        return self.value

    def __str__(self):
        return str(self.value)


class BinaryOp(Expression):
    def __init__(self, left, right, op):
        self.left = left
        self.right = right
        self.op = op

    def evaluate(self):
        left_val = self.left.evaluate()
        right_val = self.right.evaluate()

        if self.op == "+":
            return left_val + right_val
        elif self.op == "-":
            return left_val - right_val
        elif self.op == "*":
            return left_val * right_val
        elif self.op == "/":
            if right_val == 0:
                raise ValueError("Division by zero")
            return left_val / right_val

        raise ValueError(f"Unsupported binary operator: {self.op}")

    def __str__(self):
        return f"({self.left} {self.op} {self.right})"


class UnaryOp(Expression):
    def __init__(self, operand, op):
        self.operand = operand
        self.op = op

    def evaluate(self):
        val = self.operand.evaluate()

        if self.op == "neg":
            return -val
        elif self.op == "abs":
            return abs(val)

        raise ValueError(f"Unsupported unary operator: {self.op}")

    def __str__(self):
        return f"{self.op}({self.operand})"

def print_pattern(n, pattern_type):
    """
    Print a right_triangle, inverted_triangle, or diamond pattern of asterisks based on pattern_type, or "Invalid pattern".
    """
    if pattern_type == "right_triangle":
        for i in range(1, n + 1):
            print("*" * i)

    elif pattern_type == "inverted_triangle":
        for i in range(n, 0, -1):
            print("*" * i)

    elif pattern_type == "diamond":
        # Top half (including middle row of 2n - 1 asterisks)
        for i in range(1, n + 1):
            spaces = " " * (n - i)
            stars = "*" * (2 * i - 1)
            print(spaces + stars)

        # Bottom half
        for i in range(n - 1, 0, -1):
            spaces = " " * (n - i)
            stars = "*" * (2 * i - 1)
            print(spaces + stars)

    else:
        print("Invalid pattern")

