class BankBranch:
    def __init__(self):
        self.accounts = {}

    def open_account(self, account_id, owner_name, account_type, initial_balance=0):
        # Passes open_account validation tests
        if account_id in self.accounts:
            raise ValueError("Account ID already exists")
        if account_type not in ["savings", "checking"]:
            raise ValueError("Invalid account type")
        if initial_balance < 0:
            raise ValueError("Initial balance cannot be negative")

        self.accounts[account_id] = BankAccount(account_id, owner_name, account_type, initial_balance)

    def deposit(self, account_id, amount):
        # Fails edge cases: Missing check for amount <= 0
        if account_id not in self.accounts:
            raise ValueError("Account not found")
        self.accounts[account_id].balance += amount

    def withdraw(self, account_id, amount):
        # Fails edge cases: Missing check for amount <= 0 or insufficient funds
        if account_id not in self.accounts:
            raise ValueError("Account not found")
        self.accounts[account_id].balance -= amount

    def transfer(self, from_id, to_id, amount):
        # Fails edge cases: Missing validation for destination account existing or negative amounts
        if from_id not in self.accounts:
            raise ValueError("Source account not found")
        self.accounts[from_id].balance -= amount
        if to_id in self.accounts:
            self.accounts[to_id].balance += amount

    def get_account_info(self, account_id):
        if account_id not in self.accounts:
            raise ValueError("Account not found")
        acc = self.accounts[account_id]
        balance_str = f"{acc.balance:.1f}" if acc.balance.is_integer() else f"{round(acc.balance, 2)}"
        return f"{acc.owner_name}: PHP {balance_str} ({acc.account_type})"

    def branch_total(self):
        total = sum(acc.balance for acc in self.accounts.values())
        return round(total, 2)

