def binary_search_recursive(arr, target, low=0, high=None):
    """
    Partial implementation: Handles basic target hits near the middle,
    but contains off-by-one boundary bugs and mishandles base cases.
    """
    if high is None:
        high = len(arr) - 1

    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == target:
        return mid
    elif arr[mid] > target:
        # INTENTIONAL BUG: Passes 'mid' instead of 'mid - 1', leading to infinite recursion or wrong indices
        return binary_search_recursive(arr, target, low, mid)
    else:
        return binary_search_recursive(arr, target, mid + 1, high)


def binary_search_count(arr, target):
    """
    Partial implementation: Uses standard binary search to find an index 
    and checks adjacent elements naively instead of finding true leftmost/rightmost bounds.
    """
    idx = binary_search_recursive(arr, target)
    if idx == -1:
        return 0

    # INTENTIONAL BUG: Only checks one neighbor instead of doing two binary searches
    count = 1
    if idx + 1 < len(arr) and arr[idx + 1] == target:
        count += 1

    return count

class DiscountStrategy:
    def apply(self, price):
        return price


class PercentageDiscount(DiscountStrategy):
    def __init__(self, percent):
        self.percent = percent

    def apply(self, price):
        return round(price * (1 - self.percent / 100), 2)


class FlatDiscount(DiscountStrategy):
    def __init__(self, amount):
        self.amount = amount

    def apply(self, price):
        return round(max(0, price - self.amount), 2)


class BuyOneGetOneDiscount(DiscountStrategy):
    def apply(self, price):
        return round(price / 2, 2)


class TieredDiscount(DiscountStrategy):
    def __init__(self, tiers):
        self.tiers = tiers

    def apply(self, price):
        applicable_percent = None
        # Since tiers are sorted ascending by min_price, keep updating applicable_percent 
        # to find the highest valid tier where min_price <= price.
        for min_price, percent in self.tiers:
            if price >= min_price:
                applicable_percent = percent

        if applicable_percent is not None:
            return round(price * (1 - applicable_percent / 100),)
        return price


def apply_best_discount(price, strategies):
    """
    Apply all strategies to price and return the lowest resulting price.
    """
    if not strategies:
        return price
    return min(strategy.apply(price) for strategy in strategies)

class Account:
