        super().__init__(owner, balance=0)
        self.credit_limit = credit_limit

    def withdraw(self, amount):
        if amount <= 0 or (self.balance - amount) < -self.credit_limit:
            raise ValueError("Withdrawal failed: amount exceeds available credit limit.")
        self.balance -= amount

    def available_credit(self):
        return self.credit_limit + self.balance

def check_brackets(s):
    brackets = {"(":")", "[":"]", "{":"}"}
    stack = []

    for char in s:
        if char in brackets:
            stack.append(char)

        elif char in brackets.values():
            if not stack:
                return False

            top = stack.pop()
            if brackets[top] != char:
                return False

    return len(stack)==0

    pass

