def shipping_cost(weight, distance, is_express, is_fragile):
    """
    Compute and return the total shipping cost based on weight, distance, and express/fragile fees.
    """
    if weight <= 1:
        base_rate = 50.00
    elif weight <= 5:
        base_rate = 50.00 + (weight - 1) * 20.00
    else:
        base_rate = 130.00 + (weight - 5) * 15.00

    if distance <= 50:
        distance_rate = 0.00
    elif distance <= 200:
        distance_rate = 0.20
    else:
        distance_rate = 0.50

    total = base_rate + (base_rate * distance_rate)

    if is_express:
        total += 100.00

    if is_fragile:
        total += base_rate * 0.10

    return round(total, 2)

