def lca(root, p, q):
    """
    Return the value of the lowest common ancestor of the nodes with values p and q.
    """
    if root.val == q or root.val == p:
        return root.val

    left = lca(root.left, q, p)
    right = lca(root.right, q, p)

    if left is not None and right is not None:
        return root.val


    return left

