from collections import deque

def serialize(root):
    if root is None:
        return ""

    result = []
    queue = deque([root])

    while queue:
        node = queue.popleft()

        if node is None:
            result.append("null")
        else:
            result.append(str(node.val))
            queue.append(node.left)
            queue.append(node.right)

    # Remove unnecessary trailing "null" values
    while result and result[-1] == "null":
        result.pop()

    return ",".join(result)


