def binary_search_count(arr, target):
    """
    Return how many times target appears in sorted arr,
    using two binary searches.
    """

    def find_first():
        while low <= high:
            mid = (low + high) // 2

            if arr[mid] == target:
                result = mid
                high = mid - 1
            elif arr[mid] < target:
                low = mid + 1
            else:
                high = mid - 1


    def find_last():
        while low <= high:
            mid = (low + high) // 2

            if arr[mid] == target:
                result = mid
                low = mid + 1
            elif arr[mid] < target:
                low = mid + 1
            else:
                high = mid - 1

def transpose(matrix):
    """
    Return the transpose of matrix (rows become columns). Do not modify the original.
    """
    if not matrix:
        return []

    return [list(column) for column in zip(*matrix)]


def multiply(A, B):
    """
    Return the matrix product of A and B. Raise ValueError if dimensions are incompatible.
    """
    if not A or not B:
        return []

    if len(A[0]) != len(B):
        raise ValueError("Incompatible matrix dimensions")

    return [
        [sum(A[i][k] * B[k][j] for k in range(len(B)))
         for j in range(len(B[0]))]
        for i in range(len(A))
    ]

def main_diagonal(matrix):
