def unit_converter(amount, from_unit, to_unit):
    if from_unit == to_unit:
        print("Error: Unsupported conversion")
        return

    if from_unit == "km" and to_unit == "miles":
        result = amount * 0.621371
    elif from_unit == "miles" and to_unit == "km":
        result = amount / 0.621371

    elif from_unit == "kg" and to_unit == "lbs":
        result = amount * 2.20462
    elif from_unit == "lbs" and to_unit == "kg":
        result = amount / 2.20462

    elif from_unit == "liters" and to_unit == "gallons":
        result = amount * 0.264172
    elif from_unit == "gallons" and to_unit == "liters":
        result = amount / 0.264172

    else:
        print("Error: Unsupported conversion")
        return

    print(round(result, 2))

