def binary_search_recursive(arr, target, low=0, high=None):
    if high is None: 
        high = len(arr) - 1
    if low > high:
        return -1
    mid = (low + high) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return binary_search_recursive(arr, target, mid + 1, high)
    else:
        return binary_search_recursive(arr, target, low, mid - 1)
def binary_search_count(arr, target):
    def find_leftmost(arr, target, low, high):
        if low > high:
            return -1
        mid = (low + high) // 2
        if arr[mid] == target:
            # Check if this is the leftmost occurrence
            if mid == low or arr[mid - 1] != target:
                return mid
            return find_leftmost(arr, target, low, mid - 1)
        elif arr[mid] < target:
            return find_leftmost(arr, target, mid + 1, high)
        else:
            return find_leftmost(arr, target, low, mid - 1)

    def find_rightmost(arr, target, low, high):
        if low > high:
            return -1
        mid = (low + high) // 2
        if arr[mid] == target:
            # Check if this is the rightmost occurrence
            if mid == high or arr[mid + 1] != target:
                return mid
            return find_rightmost(arr, target, mid + 1, high)
        elif arr[mid] < target:
            return find_rightmost(arr, target, mid + 1, high)
        else:
            return find_rightmost(arr, target, low, mid - 1)

    left = find_leftmost(arr, target, 0, len(arr) - 1)
    if left == -1:
        return 0

    right = find_rightmost(arr, target, 0, len(arr) - 1)
    return right - left + 1

def main_diagonal(matrix):
    n = len(matrix)
    return [matrix[i][i] for i in range(n)]


def anti_diagonal(matrix):
    n = len(matrix)
    return [matrix[i][n - 1 - i] for i in range(n)]


def is_symmetric(matrix):
    n = len(matrix)
    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True


def trace(matrix):
    return sum(main_diagonal(matrix))

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def has_cycle(head):
    slow = head
    fast = head

    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next

        if slow == fast:
            return True

    return False

def find_cycle_start(head):
    slow = head
    fast = head

    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next

        if slow == fast:
            break
    else:
        return None

    pointer = head
    while pointer != slow:
        pointer = pointer.next
        slow = slow.next

    return pointer.val

class DiscountStrategy:
    def apply(self, price):
        return price


class PercentageDiscount(DiscountStrategy):
    def __init__(self, percent):
        self.percent = percent

    def apply(self, price):
        return round(price * (1 - self.percent / 100), 2)


class FlatDiscount(DiscountStrategy):
    def __init__(self, amount):
        self.amount = amount

    def apply(self, price):
        return round(max(0, price - self.amount), 2)


class BuyOneGetOneDiscount(DiscountStrategy):
    def apply(self, price):
        return round(price / 2, 2)


class TieredDiscount(DiscountStrategy):
    def __init__(self, tiers):
        self.tiers = tiers

    def apply(self, price):
        applicable_percent = None

        for min_price, percent in self.tiers:
            if min_price <= price:
                applicable_percent = percent
            else:
                break

        if applicable_percent is None:
            return price

        return round(price * (1 - applicable_percent / 100), 2)

def apply_best_discount(price, strategies):
    results = [strategy.apply(price) for strategy in strategies]
    return min(results)

class BankAccount:
    def __init__(self, account_id, owner_name, account_type, balance=0):
