        self.balance = balance


class BankBranch:
    def __init__(self):
        self.accounts = {}

    def open_account(self, account_id, owner_name, account_type, initial_balance=0):
        if account_id in self.accounts:
            raise ValueError(f"Account {account_id} already exists")
        if account_type not in ("savings", "checking"):
            raise ValueError("account_type must be 'savings' or 'checking'")
        if initial_balance < 0:
            raise ValueError("initial_balance cannot be negative")

        self.accounts[account_id] = BankAccount(
            account_id, owner_name, account_type, float(initial_balance)
        )

    def deposit(self, account_id, amount):
        if account_id not in self.accounts:
            raise ValueError(f"Account {account_id} not found")
        if amount <= 0:
            raise ValueError("amount must be positive")

        self.accounts[account_id].balance += amount

    def withdraw(self, account_id, amount):
        if account_id not in self.accounts:
            raise ValueError(f"Account {account_id} not found")
        if amount <= 0:
            raise ValueError("amount must be positive")

        account = self.accounts[account_id]
        if account.balance < amount:
            raise ValueError("insufficient funds")

        account.balance -= amount

    def transfer(self, from_id, to_id, amount):
        if from_id not in self.accounts or to_id not in self.accounts:
            raise ValueError("account not found")

        from_account = self.accounts[from_id]
        if from_account.balance < amount:
            raise ValueError("insufficient funds")

        self.withdraw(from_id, amount)
        self.deposit(to_id, amount)

    def get_account_info(self, account_id):
        if account_id not in self.accounts:
            raise ValueError(f"Account {account_id} not found")

        account = self.accounts[account_id]
        return f"{account.owner_name}: PHP {round(float(account.balance), 2)} ({account.account_type})"

    def branch_total(self):
        total = sum(account.balance for account in self.accounts.values())
        return round(float(total), 2)

class TicketBooking:
    def __init__(self):
        self.__seats = {}

    def add_seat(self, seat_id, price):
        if seat_id in self.__seats:
            raise ValueError(f"Seat {seat_id} already exists")
        if price <= 0:
            raise ValueError("price must be positive")

        self.__seats[seat_id] = {
            "status": "available",
            "holder": None,
            "price": float(price),
        }

    def book_seat(self, seat_id, holder_name):
        if seat_id not in self.__seats:
            raise ValueError(f"Seat {seat_id} not found")

        seat = self.__seats[seat_id]
        if seat["status"] == "booked":
            raise ValueError(f"Seat {seat_id} already booked")

        seat["status"] = "booked"
        seat["holder"] = holder_name

    def cancel_booking(self, seat_id):
        if seat_id not in self.__seats:
            raise ValueError(f"Seat {seat_id} not found")

        seat = self.__seats[seat_id]
        if seat["status"] != "booked":
            raise ValueError(f"Seat {seat_id} is not booked")

        seat["status"] = "available"
        seat["holder"] = None

    def available_seats(self):
        return sorted(
            seat_id
            for seat_id, seat in self.__seats.items()
            if seat["status"] == "available"
        )

    def get_booking(self, seat_id):
        if seat_id not in self.__seats:
            raise ValueError(f"Seat {seat_id} not found")

        seat = self.__seats[seat_id]
        if seat["status"] == "booked":
            return f"{seat_id}: {seat['holder']}"
        return f"{seat_id}: available"

    def total_revenue(self):
        total = sum(
            seat["price"]
            for seat in self.__seats.values()
            if seat["status"] == "booked"
        )
        return round(float(total), 2)

class MinStack:
    def __init__(self):
        self.__stack = []
        self.__min_stack = []

    def push(self, item):
        self.__stack.append(item)

        if not self.__min_stack or item <= self.__min_stack[-1]:
            self.__min_stack.append(item)
        else:
            self.__min_stack.append(self.__min_stack[-1])

    def pop(self):
        if self.is_empty():
            raise IndexError("pop from empty stack")

        self.__min_stack.pop()
        return self.__stack.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError("peek from empty stack")

        return self.__stack[-1]

    def get_min(self):
        if self.is_empty():
            raise IndexError("get_min from empty stack")

        return self.__min_stack[-1]

    def is_empty(self):
        return len(self.__stack) == 0

class ShoppingCart:
    def __init__(self):
        self.__items = {}

    def add_item(self, name, price, quantity=1):
        if price <= 0:
            raise ValueError("price must be positive")
        if quantity <= 0:
            raise ValueError("quantity must be positive")

        if name in self.__items:
            existing_price, existing_quantity = self.__items[name]
            self.__items[name] = (existing_price, existing_quantity + quantity)
        else:
            self.__items[name] = (float(price), quantity)

    def remove_item(self, name, quantity=1):
        if name not in self.__items:
            raise ValueError(f"Item {name} not found")

        price, current_quantity = self.__items[name]
        if quantity > current_quantity:
            raise ValueError("quantity to remove exceeds current quantity")

        new_quantity = current_quantity - quantity
        if new_quantity == 0:
            del self.__items[name]
        else:
            self.__items[name] = (price, new_quantity)

    def get_total(self):
        total = sum(price * quantity for price, quantity in self.__items.values())
        return round(float(total), 2)

    def get_item_count(self):
        return sum(quantity for _, quantity in self.__items.values())

    def apply_discount(self, percent):
        if not (0 <= percent <= 100):
            raise ValueError("percent must be between 0 and 100")

        total = self.get_total()
        return round(float(total * (1 - percent / 100)), 2)

    def __str__(self):
        return f"Cart: {self.get_item_count()} items, Total: {self.get_total()}"

class InventoryManager:
    def __init__(self):
        self.__inventory = {}

    def add_item(self, name, price, stock, category):
        if name in self.__inventory:
            raise ValueError(f"Item {name} already exists")
        if price <= 0:
            raise ValueError("price must be positive")
        if stock < 0:
            raise ValueError("stock cannot be negative")

        self.__inventory[name] = {
            "price": float(price),
            "stock": stock,
            "category": category,
        }

    def restock(self, name, quantity):
        if name not in self.__inventory:
            raise ValueError(f"Item {name} not found")
        if quantity <= 0:
            raise ValueError("quantity must be positive")

        self.__inventory[name]["stock"] += quantity

    def sell(self, name, quantity):
        if name not in self.__inventory:
            raise ValueError(f"Item {name} not found")
        if quantity <= 0:
            raise ValueError("quantity must be positive")

        item = self.__inventory[name]
        if item["stock"] < quantity:
            raise ValueError("insufficient stock")

        item["stock"] -= quantity

    def get_by_category(self, category):
        return sorted(
            name
            for name, item in self.__inventory.items()
            if item["category"] == category
        )

    def total_value(self):
        total = sum(
            item["price"] * item["stock"] for item in self.__inventory.values()
        )
        return round(float(total), 2)

    def low_stock_alert(self, threshold=5):
        return sorted(
            name
            for name, item in self.__inventory.items()
            if item["stock"] <= threshold
        )

class CircularQueue:
    def __init__(self, capacity):
        self.__capacity = capacity
        self.__buffer = [None] * capacity
        self.__front = 0
        self.__count = 0

    def enqueue(self, item):
        if self.is_full():
            raise OverflowError("queue is full")

        rear = (self.__front + self.__count) % self.__capacity
        self.__buffer[rear] = item
        self.__count += 1

    def dequeue(self):
        if self.is_empty():
            raise IndexError("dequeue from empty queue")

        item = self.__buffer[self.__front]
        self.__buffer[self.__front] = None
        self.__front = (self.__front + 1) % self.__capacity
        self.__count -= 1
        return item

    def peek(self):
        if self.is_empty():
            raise IndexError("peek from empty queue")

        return self.__buffer[self.__front]

    def is_full(self):
        return self.__count == self.__capacity

    def is_empty(self):
        return self.__count == 0

    def size(self):
        return self.__count

