class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def sorted_array_to_bst(nums):
    if not nums:
        return None

    def build(lo, hi):
        if lo > hi:
            return None
        mid = (lo + hi) // 2          # lower middle for even-length ranges
        node = TreeNode(nums[mid])
        node.left = build(lo, mid - 1)
        node.right = build(mid + 1, hi)
        return node

    return build(0, len(nums) - 1)


def is_valid_bst(root):
    def validate(node, low, high):
        if node is None:
            return True
        if low is not None and node.val <= low:
            return False
        return validate(node.left, low, node.val) and validate(node.right, node.val, high)

    return validate(root, None, None)


def max_depth(root):
    if root is None:
        return 0
    return 1 + max(max_depth(root.left), max_depth(root.right))


def tree_to_inorder(root):
    result = []

    def inorder(node):
        if node is None:
            return
        inorder(node.left)
        result.append(node.val)
        inorder(node.right)

    inorder(root)
    return result

from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def serialize(root):
    if root is None:
        return ""

    values = []
    queue = deque([root])

    while queue:
        node = queue.popleft()

    return ",".join(values)


def deserialize(data):
    if data == "":
        return None


    while queue and i < len(values):
        node = queue.popleft()

        if values[i] != "null":
            node.left = TreeNode(int(values[i]))
            queue.append(node.left)
        i += 1

        if i < len(values) and values[i] != "null":
            node.right = TreeNode(int(values[i]))
            queue.append(node.right)
        i += 1

    return root


def tree_to_level_order(root):
    if root is None:
        return []

    result = []
    queue = deque([root])

    while queue:
        level_size = len(queue)
        level = []
        for _ in range(level_size):
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(level)

    return result

import random


def _validate(arr, k):
    if not arr:
        raise ValueError("List is empty")
    if k < 1 or k > len(arr):
        raise ValueError("k is out of range")


def kth_largest_sort(arr, k):
    _validate(arr, k)
    sorted_arr = sorted(arr, reverse=True)
    return sorted_arr[k - 1]


def kth_largest_quickselect(arr, k):
    _validate(arr, k)

    # Bug: uses k-1 directly as the ascending-order index instead of
    # converting to len(arr) - k, so this actually finds the kth SMALLEST
    # element rather than the kth largest.
    target_index = k - 1
    nums = list(arr)

    def partition(left, right, pivot_index):
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] < pivot_value:
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def select(left, right, index):
        while True:
            if left == right:
                return nums[left]
            pivot_index = random.randint(left, right)
            pivot_index = partition(left, right, pivot_index)
            if index == pivot_index:
                return nums[index]
            elif index < pivot_index:
                right = pivot_index - 1
            else:
                left = pivot_index + 1

    return select(0, len(nums) - 1, target_index)

class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        self.balance += amount

    def withdraw(self, amount):
        if amount <= 0 or amount > self.balance:
            raise ValueError("Invalid withdrawal")
        self.balance -= amount

    def get_balance(self):
        return self.balance

    def __str__(self):
        return f"{self.owner}'s Account: PHP {self.balance}"


class SavingsAccount(Account):
    def __init__(self, owner, balance, interest_rate):
        super().__init__(owner, balance)
        self.interest_rate = interest_rate

    def apply_interest(self):
        self.balance = round(
            self.balance * (1 + self.interest_rate / 100), 2
        )

    def withdraw(self, amount):
        if amount <= 0 or self.balance - amount < 500:
            raise ValueError("Savings balance cannot fall below 500")
        self.balance -= amount


class CreditAccount(Account):
    def __init__(self, owner, credit_limit):
        super().__init__(owner, 0)
        self.credit_limit = credit_limit

    def withdraw(self, amount):
        if amount <= 0 or self.balance - amount < -self.credit_limit:
            raise ValueError("Credit limit exceeded")
        self.balance -= amount

    def available_credit(self):
        return self.credit_limit + self.balance

def grade_report(students):
    result = []

    for name, grades in students:
        if not grades:
            average = 0.0
            standing = "No grades"
        else:
            average = round(sum(grades) / len(grades), 2)

            if average >= 90:
                standing = "Excellent"
            elif average >= 75:
                standing = "Good"
            elif average >= 60:
                standing = "Passing"
            else:
                standing = "Failing"

        result.append((name, average, standing))

    return sorted(result, key=lambda x: (-x[1], x[0]))

