class ReportSection:
    def __init__(self, title, data):
        self.title = title
        self.data = data

    def generate(self):
        if not self.data:
            return f"=== {self.title} ===\n(no data)"
        return f"=== {self.title} ===\n" + "\n".join(str(x) for x in self.data)

    def summary(self):
        return f"{self.title}: {len(self.data)} item(s)"


class TableSection(ReportSection):
    def __init__(self, title, data, headers):
        super().__init__(title, data)
        self.headers = headers

    def generate(self):
        if not self.data:
            return f"=== {self.title} ===\n(no data)"

        widths = []

        for i, header in enumerate(self.headers):
            max_width = len(str(header))

            for row in self.data:
                max_width = max(max_width, len(str(row[i])))

            widths.append(max_width)

        header_line = " | ".join(
            str(self.headers[i]).ljust(widths[i])
            for i in range(len(self.headers))
        )

        rows = []
        for row in self.data:
            rows.append(
                " | ".join(
                    str(row[i]).ljust(widths[i])
                    for i in range(len(row))
                )
            )

        return f"=== {self.title} ===\n{header_line}\n" + "\n".join(rows)


class ChartSection(ReportSection):
    def generate(self):
        if not self.data:
            return f"=== {self.title} ===\n(no data)"

        width = max(len(str(label)) for label, value in self.data)

        rows = []
        for label, value in self.data:
            rows.append(f"{str(label).ljust(width)} {'#' * value}")

        return f"=== {self.title} ===\n" + "\n".join(rows)


class SummarySection(ReportSection):
    def __init__(self, title, sections):
        super().__init__(title, [])
        self.sections = sections

    def generate(self):
        summaries = [section.summary() for section in self.sections]
        return f"=== {self.title} ===\n" + "\n".join(summaries)


def build_report(sections):
    return "\n\n".join(section.generate() for section in sections)

def simple_calculator(a, b, op):
    if op not in ("+", "-", "*", "/"):
        print("Error: Unknown operator")
        return

    if op == "/":
        if b == 0:
            print("Error: Division by zero")
            return
        result = a / b
    elif op == "+":
        result = a + b
    elif op == "-":
        result = a - b
    elif op == "*":
        result = a * b

    print(f"{result:.2f}")

def bmi_classifier(weight, height):
    if height <= 0 or weight <= 0:
        print("Invalid input")
        return

    bmi = weight / (height ** 2)
    rounded_bmi = f"{bmi:.2f}"

    bmi_value = float(rounded_bmi)

    if bmi_value < 18.5:
        category = "Underweight"
    elif 18.5 <= bmi_value < 25.0:
        category = "Normal weight"
    elif 25.0 <= bmi_value < 30.0:
        category = "Overweight"
    else:
        category = "Obese"

    print(f"BMI: {rounded_bmi} — {category}")

