class Library:
    def __init__(self):
        self.books = {}

    def add_book(self, title: str, author: str):
        self.books[title] = Book(title, author)

    def borrow_book(self, title: str):
        if title not in self.books:
            raise ValueError(f"Book '{title}' not found in library.")
        if not self.books[title].available:
            raise ValueError(f"Book '{title}' is already borrowed.")
        self.books[title].available = False

    def return_book(self, title: str):
        if title not in self.books:
            raise ValueError(f"Book '{title}' not found in library.")
        if self.books[title].available:
            raise ValueError(f"Book '{title}' is not currently borrowed.")
        self.books[title].available = True

    def available_books(self) -> list:
        return sorted([
            book.title for book in self.books.values() if book.available
        ])

    def search_by_author(self, author: str) -> list:
        return sorted([
            book.title for book in self.books.values() if book.author == author
        ])

class Product:
    def __init__(self, name, price, stock):
        self.name = name
        self.price = float(price)
        self.stock = int(stock)

class Store:
    def __init__(self):
        self.products = {}

    def add_product(self, name, price, stock):
        self.products[name] = Product(name, price, stock)

    def buy(self, name, quantity):
        if name not in self.products:
            raise ValueError("Product not found")
        if quantity <= 0:
            raise ValueError("Quantity must be greater than 0")
        if self.products[name].stock < quantity:
            raise ValueError("Insufficient stock")

        self.products[name].stock -= quantity

    def restock(self, name, quantity):
        if name not in self.products:
            raise ValueError("Product not found")
        if quantity <= 0:
            raise ValueError("Quantity must be greater than 0")

        self.products[name].stock += quantity

    def total_value(self):
        total = sum(product.price * product.stock for product in self.products.values())
        return round(total, 2)

    def available_products(self):
        available = [name for name, product in self.products.items() if product.stock > 0]
        return sorted(available)

class StudentManager:
    def __init__(self):
        self.student_courses = {}
        self.course_students = {}

    def enroll(self, student_name, course_name):
        if student_name not in self.student_courses:
            self.student_courses[student_name] = set()
        if course_name not in self.course_students:
            self.course_students[course_name] = set()


        if course_name in self.student_courses[student_name]:
            raise ValueError("Student is already enrolled in this course.")


        self.student_courses[student_name].add(course_name)
        self.course_students[course_name].add(student_name)

    def drop(self, student_name, course_name):

        if student_name not in self.student_courses or course_name not in self.student_courses[student_name]:
            raise ValueError("Student is not enrolled in this course.")


        self.student_courses[student_name].remove(course_name)
        self.course_students[course_name].remove(student_name)


        if not self.student_courses[student_name]:
            del self.student_courses[student_name]
        if not self.course_students[course_name]:
            del self.course_students[course_name]

    def get_courses(self, student_name):

        return sorted(list(self.student_courses.get(student_name, [])))

    def get_students(self, course_name):

        return sorted(list(self.course_students.get(course_name, [])))

    def top_student(self):
        if not self.student_courses:
            return None

        best_student = None
        max_courses = 0

        for student, courses in self.student_courses.items():
            num_courses = len(courses)

            if num_courses > max_courses:
                best_student = student
                max_courses = num_courses
            elif num_courses == max_courses:
                if best_student is None or student < best_student:
                    best_student = student

        return best_student

