def transform_string(text, operations):
    """
    Apply each operation in operations to text in order, and return the result. Unrecognized ops are skipped.
    """
    for op in operations:
        if op == "upper":
            text = text.upper()
        elif op == "lower":
            text = text.lower()
        elif op == "title":
            text = text.title()
        elif op == "reverse":
            text = text[::-1]
        elif op == "strip":
            text = text.strip()
        elif op == "remove_spaces":
            text = text.replace(" ", "")
        elif op == "replace_vowels":
            text = "".join("*" if c in "aeiouAEIOU" else c for c in text)
        # unrecognized ops are skipped
    return text

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

def fibonacci(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

def sum_digits(n):
    if n == 0:
        return 0
    return n % 10 + sum_digits(n // 10)

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def get_config(config, key_path, default=None):
    """
    Retrieve a value from a nested dict via a dot-separated key_path, or return default.
    """
    keys = key_path.split(".")
    current = config
    for key in keys:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current

def set_config(config, key_path, value):
    """
    Set a value in a nested dict via a dot-separated key_path, creating dicts as needed. Modifies config in place and returns it.
    """
    keys = key_path.split(".")
    current = config
    for key in keys[:-1]:
        if key not in current or not isinstance(current[key], dict):
            current[key] = {}
        current = current[key]
    current[keys[-1]] = value
    return config

def flatten_config(config, prefix=""):
    """
    Flatten a nested dict into a single-level dict with dot-separated keys.
    """
    result = {}
    for key, value in config.items():
        full_key = f"{prefix}.{key}" if prefix else key
        if isinstance(value, dict):
            result.update(flatten_config(value, full_key))
        else:
            result[full_key] = value
    return result

def build_index(documents):
    """
    Return an inverted index: word -> sorted list of document indices containing it.
    """
    index = {}
    for doc_idx, doc in enumerate(documents):
        words = doc.split()
        cleaned = {w.strip('.,!?').lower() for w in words}
        cleaned.discard("")
        for word in cleaned:
            index.setdefault(word, []).append(doc_idx)
    for word in index:
        index[word].sort()
    return index

