def shipping_cost(weight, distance, is_express, is_fragile):
    """
    Compute and return the total shipping cost based on weight, distance, and express/fragile fees.
    """
    if weight <= 1:
        base = 50.00
    elif weight <= 5:
        base = 50.00 + (weight - 1) * 20.00
    else:
        base = 130.00 + (weight - 5) * 20.00

    if distance <= 50:
        mult = 1.0
    elif distance <= 200:
        mult = 1.20
    else:
        mult = 1.50

    total = base * mult
    if is_fragile:
        total += base * 0.10
    if is_express:
        total += 100.00
    return round(total, 2)

def ticket_price(age, day, is_member):
    """
    Compute and return the final ticket price based on age, day-of-week adjustment, and membership discount.
    """
    if age < 0:
        return "Invalid age"
    valid_days = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"}
    if day not in valid_days:
        return "Invalid day"

    if age < 5:
        base = 0.0
    elif age <= 12:
        base = 150.0
    elif age <= 17:
        base = 250.0
    elif age <= 59:
        base = 350.0
    else:
        base = 250.0

    price = base
    if day in ("Tuesday", "Wednesday"):
        price = price * 0.80
    if day in ("Saturday", "Sunday"):
        price = price + 50
    if is_member:
        price = price * 0.90
    return round(price, 2)

