        self.specialty = specialty

class HospitalSystem:
    def __init__(self):
        self.doctors = {}
        self.appointments = {}  # doctor_id -> {date: patient_name}
        self.patient_appointments = {}  # patient_name -> set of doctor_id

    def add_doctor(self, doctor_id, name, specialty):
        if doctor_id in self.doctors:
            raise ValueError("Doctor ID already exists")
        self.doctors[doctor_id] = Doctor(doctor_id, name, specialty)
        self.appointments[doctor_id] = {}

    def book_appointment(self, patient_name, doctor_id, date):
        if doctor_id not in self.doctors:
            raise ValueError("Doctor not found")
        self.appointments[doctor_id][date] = patient_name
        self.patient_appointments.setdefault(patient_name, set()).add(doctor_id)

    def cancel_appointment(self, patient_name, doctor_id, date):
        if doctor_id not in self.appointments or self.appointments[doctor_id].get(date) != patient_name:
            raise ValueError("Appointment not found")
        del self.appointments[doctor_id][date]
        self.patient_appointments[patient_name].discard(doctor_id)

    def get_appointments(self, doctor_id):
        if doctor_id not in self.doctors:
            raise ValueError("Doctor not found")
        entries = [f"{date}: {name}" for date, name in self.appointments[doctor_id].items()]
        return sorted(entries)

    def get_patient_doctors(self, patient_name):
        doctor_ids = self.patient_appointments.get(patient_name, set())
        return sorted(doctor_ids)

class ParkingSlot:
    def __init__(self, slot_id, floor, is_occupied=False, vehicle_plate=None):
        self.slot_id = slot_id
        self.floor = floor
        self.is_occupied = is_occupied
        self.vehicle_plate = vehicle_plate

class ParkingLot:
    def __init__(self):
        self.slots = {}
        self.vehicle_to_slot = {}

    def add_slot(self, slot_id, floor):
        if slot_id in self.slots:
            raise ValueError("Slot already exists")
        self.slots[slot_id] = ParkingSlot(slot_id, floor)

    def park(self, vehicle_plate, preferred_floor=None):
        if vehicle_plate in self.vehicle_to_slot:
            raise ValueError("Vehicle already parked")

        available = [s for s in self.slots.values() if not s.is_occupied]
        available.sort(key=lambda s: (s.floor, s.slot_id))
        candidate = available[0]

        candidate.is_occupied = True
        candidate.vehicle_plate = vehicle_plate
        self.vehicle_to_slot[vehicle_plate] = candidate.slot_id

    def leave(self, vehicle_plate):
        if vehicle_plate not in self.vehicle_to_slot:
            raise ValueError("Vehicle not found")
        slot_id = self.vehicle_to_slot.pop(vehicle_plate)
        slot = self.slots[slot_id]
        slot.is_occupied = False
        slot.vehicle_plate = None

    def find_vehicle(self, vehicle_plate):
        if vehicle_plate not in self.vehicle_to_slot:
            raise ValueError("Vehicle not found")
        slot_id = self.vehicle_to_slot[vehicle_plate]
        slot = self.slots[slot_id]
        return f"Floor {slot.floor}, Slot {slot.slot_id}"

    def available_count(self):
        return sum(1 for s in self.slots.values() if not s.is_occupied)

    def occupied_slots(self):
        entries = [f"{s.slot_id} ({s.vehicle_plate})" for s in self.slots.values() if s.is_occupied]
        return sorted(entries)

def simulate_queue(customers):
    """
    Simulate a FIFO service counter and return {name: finish_minute} for each customer.
    """
    result = {}
    for i, (name, service_time) in enumerate(customers):
        start = i * service_time
        finish = start + service_time
        result[name] = finish
    return result

