def sum_of_multiples(n, k):
    """
    Print the sum of all multiples of k from 1 to n inclusive.
    """
    if n >= k:
        total = 0
        for i in range(1, n + 1):
            if i % k == 0:
                total += i
        print(total)
    else:
        print()

def group_by(items):
    """
    Return a dict mapping category -> sorted list of values, given a list of (category, value) tuples.
    """
    result = {}
    for category, value in items:
        result.setdefault(category, []).append(value)
    return result

