def count_occurrences(text, sub):
    return text.lower().count(sub.lower())
    pass

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result
    pass

def binary_search_recursive(arr, target, low=0, high=None):
    if high is None:
        high = len(arr) - 1

    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == target:
        return mid

    elif arr[mid] < target:
        return binary_search_recursive(arr, target, mid + 1, high)

    else:
        return binary_search_recursive(arr, target, low, mid - 1)
    pass

def binary_search_count(arr, target):

    def find_boundary(arr, target, is_first):
        low, high = 0, len(arr) - 1
        result = -1

        while low <= high:
            mid = (low + high) // 2

            if arr[mid] == target:
                result = mid
                if is_first:
                    high = mid - 1 
                else:
                    low = mid + 1  
            elif arr[mid] < target:
                low = mid + 1
            else:
                high = mid - 1

        return result

    left_idx = find_boundary(arr, target, True)

    if left_idx == -1:
        return 0

    right_idx = find_boundary(arr, target, False)

    return right_idx - left_idx + 1
    pass

def group_by(items):
    """
    Return a dict mapping category -> sorted list of values, given a list of (category, value) tuples.
    """
    result = {}

    for category, value in items:
        if category not in result:
            result[category] = []

        result[category].append(value)

    for category in result:
        result[category].sort()

    return result

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def bst_insert(root, val):
    """
    Insert val into the BST iteratively and return the root. Unchanged if val already exists.
    """
    if not root:
        return TreeNode(val)

    curr = root
    while curr:
        if val == curr.val:
            return root
        elif val < curr.val:
            if not curr.left:
                curr.left = TreeNode(val)
                return root
            curr = curr.left
        else:
            if not curr.right:
                curr.right = TreeNode(val)
                return root
            curr = curr.right

    return root


def bst_search(root, val):
    """
    Return True if val exists in the BST, iteratively.
    """
    curr = root
    while curr:
        if val == curr.val:
            return True
        elif val < curr.val:
            curr = curr.left
        else:
            curr = curr.right
    return False

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def is_symmetric(root):
    """
    Return True if the tree is symmetric around its center, solved iteratively without imports.
    """
    if not root:
        return True

    queue = [(root.left, root.right)]

    while queue:
        t1, t2 = queue.pop(0)

        if not t1 and not t2:
            continue
        if not t1 or not t2:
            return False
        if t1.val != t2.val:
            return False

        # Enqueue mirror pairs: outer pair, then inner pair
        queue.append((t1.left, t2.right))
        queue.append((t1.right, t2.left))

    return True

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def inorder(root):
    """
    Return node values via iterative inorder traversal (explicit stack).
    """
    res, stack = [], []
    curr = root
    while curr or stack:
        while curr:
            stack.append(curr)
            curr = curr.left
        curr = stack.pop()
        res.append(curr.val)
        curr = curr.right
    return res


def preorder(root):
    """
    Return node values via iterative preorder traversal (explicit stack).
    """
    if not root:
        return []
    res, stack = [], [root]
    while stack:
        node = stack.pop()
        res.append(node.val)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)
    return res


def postorder(root):
    """
    Return node values via iterative postorder traversal (explicit stack).
    """
    if not root:
        return []
    res, stack = [], [root]
    while stack:
        node = stack.pop()
        res.append(node.val)
        if node.left:
            stack.append(node.left)
        if node.right:
            stack.append(node.right)
    return res[::-1]

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def ll_sum(head):
    total = 0
    curr = head

    while curr:
        total += curr.val
        curr = curr.next

    return total


def ll_to_list(head):
    result = []
    curr = head

    while curr:
        result.append(curr.val)
        curr = curr.next

    return result


def list_to_ll(values):
    if not values:
        return None

    head = ListNode(values[0])
    curr = head

    for val in values[1:]:
        curr.next = ListNode(val)
        curr = curr.next

    return head

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def merge_sorted(l1, l2):
    """
    Merge two sorted linked lists into one sorted linked list
    (relink nodes, don't create new ones) and return the head.
    """
    dummy = ListNode()
    curr = dummy

    while l1 is not None and l2 is not None:
        if l1.val <= l2.val:
            curr.next = l1
            l1 = l1.next
        else:
            curr.next = l2
            l2 = l2.next

        curr = curr.next

    if l1 is not None:
        curr.next = l1
    else:
        curr.next = l2

    return dummy.next

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def delete_node(head, val):
    """
    Delete the first node whose value equals val and return the head. Unchanged if not found.
    """
    if head is not None and head.val == val:
        return head.next

    current = head
    while current is not None and current.next is not None:
        if current.next.val == val:
            current.next = current.next.next
            return head
        current = current.next

    return head

def safe_convert(value, target_type):
    """
    Convert value (a string) to target_type ("int"/"float"/"bool"), or return None if conversion fails.
    """
    try:
        if target_type == "int":
            return int(value)
        elif target_type == "float":
            return float(value)
        elif target_type == "bool":
            val_lower = value.strip().lower()
            if val_lower in ("true", "1"):
                return True
            elif val_lower in ("false", "0"):
                return False
            return None
    except (ValueError, TypeError):
        return None

    return None
